import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/routing/app_router.dart';import '../../../providers/auth_provider.dart';import '../../../providers/incident_provider.dart';import '../../../shared/widgets/loading_indicator.dart';import '../../../shared/widgets/error_message.dart';import '../widgets/dashboard_summary.dart';import '../widgets/quick_action_card.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{@override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)context.read<IncidentProvider>().subscribeToIncidents();});}
@override Widget build(BuildContext context){final auth=context.watch<AuthProvider>();final inc=context.watch<IncidentProvider>();return Scaffold(appBar:AppBar(title:const Text('Campus reports'),actions:[IconButton(onPressed:()=>Navigator.pushNamed(context,AppRouter.profile),icon:const Icon(Icons.person_outline))]),body:inc.isLoading&&inc.incidents.isEmpty?const LoadingIndicator():inc.error!=null?ErrorMessage(message:inc.error!,onRetry:inc.subscribeToIncidents):ListView(padding:const EdgeInsets.all(16),children:[Text('Hello, ${auth.profile?.name??'there'}',style:Theme.of(context).textTheme.headlineSmall),const Text('Help make our campus safer and better maintained.'),const SizedBox(height:16),DashboardSummary(count:inc.incidents.length),QuickActionCard(title:'Report an issue',subtitle:'Tell campus staff what needs attention',icon:Icons.add_circle_outline,onTap:()=>Navigator.pushNamed(context,AppRouter.createIncident)),QuickActionCard(title:'Browse incidents',subtitle:'Search and filter campus reports',icon:Icons.list_alt,onTap:()=>Navigator.pushNamed(context,AppRouter.incidents)),QuickActionCard(title:'My reports',subtitle:'Track incidents you submitted',icon:Icons.person_pin_outlined,onTap:()=>Navigator.pushNamed(context,AppRouter.myIncidents)),if(auth.isStaff)QuickActionCard(title:'Staff dashboard',subtitle:'Review reports and update status',icon:Icons.admin_panel_settings_outlined,onTap:()=>Navigator.pushNamed(context,AppRouter.staff)),QuickActionCard(title:'Settings',subtitle:'Appearance and preferences',icon:Icons.settings_outlined,onTap:()=>Navigator.pushNamed(context,AppRouter.settings))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>Navigator.pushNamed(context,AppRouter.createIncident),icon:const Icon(Icons.add),label:const Text('Report')));}}
